def transform(grid):
 h=len(grid); w=len(grid[0]); out=[[0]*w for _ in range(h)]
 # Locate the square container.
 boxes=[]
 for r in range(h):
  for c in range(w):
   color=grid[r][c]
   if not color: continue
   for n in range(4,min(h-r,w-c)+1):
    if all(grid[r][c+i]==color and grid[r+n-1][c+i]==color and grid[r+i][c]==color and grid[r+i][c+n-1]==color for i in range(n)):
     boxes.append((r,c,n,color))
 if not boxes: return out
 r,c,n,color=boxes[0]
 k=n-2
 size=4
 for i in range(k):
  for j in range(k):
   v=grid[r+1+i][c+1+j]
   if not v: continue
   y=round(i*(h-size)/(k-1)); x=round(j*(w-size)/(k-1))
   for a in range(size):
    for b in range(size):
     if a in (0,size-1) or b in (0,size-1): out[y+a][x+b]=v
   out[y+1+(r>0)][x+1+(c>0)]=color
 return out

